<template>
  <component
    :is="tag"
    :class="itemClass"
    role="listitem"
    @click="onRootClick"
  >
    <component
      :is="actionable ? 'ui-button' : 'div'"
      v-if="usesRowLayout"
      v-bind="actionBind"
      :class="actionable ? undefined : 'ui-list-item-row'"
      @click="onClick"
    >
      <span :class="actionable ? 'ui-list-item-row' : 'contents'">
        <ui-icon-tile
          v-if="icon"
          :icon="icon"
          :icon-type="iconType"
          :color="iconColor"
          :hex="iconHex"
          :variant="resolvedIconVariant"
          :size="tileSize"
        />
        <span
          v-else-if="$slots.prefix"
          class="ui-list-item-prefix-slot shrink-0"
        >
          <slot name="prefix" />
        </span>

        <span class="ui-list-item-text">
          <span :class="titleClass">
            <slot name="title">{{ title }}</slot>
          </span>
          <span
            v-if="description || $slots.description"
            class="ui-list-item-description"
          >
            <slot name="description">{{ description }}</slot>
          </span>
          <slot />
        </span>

        <span
          v-if="hasValue || placeholder || $slots.trailing"
          class="ui-list-item-trailing"
        >
          <span
            v-if="hasValue"
            class="ui-list-item-value"
          >
            <img
              v-if="valueImage"
              :src="valueImage"
              alt=""
              class="ui-list-item-value-image"
              loading="lazy"
            >
            <span
              v-if="valueSwatch"
              class="ui-list-item-value-swatch"
              :style="{ backgroundColor: valueSwatch }"
              aria-hidden="true"
            />
            <ui-icon
              v-if="valueIcon"
              :name="valueIcon"
              :type="resolvedValueIconType"
              size="sm"
              class="ui-list-item-value-icon"
            />
            <span
              v-if="value"
              class="ui-list-item-value-text"
            >{{ value }}</span>
          </span>
          <span
            v-else-if="placeholder"
            class="ui-list-item-value ui-list-item-value--placeholder"
          >{{ placeholder }}</span>
          <slot name="trailing" />
        </span>

        <span
          v-if="resolvedTrailingIcon"
          class="ui-list-item-chevron"
          aria-hidden="true"
        >
          <ui-icon
            :name="resolvedTrailingIcon"
            type="solid"
            size="sm"
            :class="trailingIcon === 'chevron' ? 'ui-icon--dir' : undefined"
          />
        </span>
      </span>
    </component>

    <ui-button
      v-if="showClear"
      type="button"
      variant="ghost"
      color="secondary"
      size="sm"
      cubed
      prefix-icon="xmark"
      class="ui-list-item-clear"
      :aria-label="resolvedClearLabel"
      @click.stop="$emit('clear')"
    />

    <template v-if="!usesRowLayout">
      <span
        v-if="prefixIcon"
        class="ui-list-item-prefix"
        aria-hidden="true"
      >
        <ui-icon
          :name="prefixIcon"
          :type="resolvedPrefixIconType"
          size="xs"
          class="ui-list-item-prefix-icon"
        />
      </span>
      <span
        v-else-if="$slots.prefix"
        class="ui-list-item-prefix-slot shrink-0"
      >
        <slot name="prefix" />
      </span>
      <div class="ui-list-item-content min-w-0 flex-1">
        <slot />
      </div>
      <div
        v-if="$slots.trailing"
        class="ui-list-item-trailing shrink-0"
      >
        <slot name="trailing" />
      </div>
    </template>
  </component>
</template>

<script>
import { cn } from '../utils/cn.js'
import { resolveUiText } from '../utils/resolve-ui-text.js'
import { iconTypeProp } from '../theme/icon-type-prop.js'
import { resolveThemeIconType } from '../theme/resolve-theme-default.js'
import { uiDefaultsMixin } from '../theme/ui-defaults.js'
import { CONTROL_SIZES } from '../utils/sizes.js'

const ALIGNS = ['start', 'center']
const TAGS = ['li', 'div']
const SIZES = CONTROL_SIZES
const ITEM_COLORS = ['danger', 'primary']
const TRAILING_ICONS = ['chevron', 'external', 'copy', 'none']

const TILE_SIZE_BY_ITEM = {
  sm: 'sm',
  md: 'sm',
  lg: 'md',
}

/**
 * Liste satırı.
 *
 * Serbest içerik: varsayılan slot + `prefix` / `trailing` slotları veya `prefixIcon` (geriye uyumlu).
 * Satır düzeni: `title` / `description` / `value` / `icon` verildiğinde ikon karosu, başlık, açıklama,
 * sağda değer ve (tıklanabilirse) chevron. `to` veya `interactive` satırı düğme / bağlantı yapar.
 */
export default {
  name: 'ListItem',
  mixins: [uiDefaultsMixin],
  props: {
    /** Dolu daire içinde `ui-icon` (ör. `check`) — serbest içerik düzeni. */
    prefixIcon: {
      type: String,
      default: null,
    },
    prefixIconType: iconTypeProp,
    /** Prefiks / trailing ile dikey hizalama (`center` medya satırları için). */
    align: {
      type: String,
      default: 'start',
      validator: (v) => ALIGNS.includes(v),
    },
    /** `div`: `role="list"` taşıyan `div` içinde (ör. kart içi ayar listesi) */
    tag: {
      type: String,
      default: 'li',
      validator: (v) => TAGS.includes(v),
    },
    title: {
      type: String,
      default: '',
    },
    description: {
      type: String,
      default: '',
    },
    /** Sağdaki kısa durum metni (chevron'un solunda) */
    value: {
      type: String,
      default: '',
    },
    /**
     * Değerin önündeki ikon — değerin türünü bir bakışta anlatır (cihaz, işletim sistemi, tarayıcı, kaynak).
     * Marka ikonları için `value-icon-type="brands"`.
     */
    valueIcon: {
      type: String,
      default: '',
    },
    valueIconType: iconTypeProp,
    /**
     * Değerin önünde renk noktası (CSS rengi) — renk seçimi satırı ("Renk ●").
     * `value-icon` / `value-swatch` tek başına da değer sayılır (metinsiz gösterilir).
     */
    valueSwatch: {
      type: String,
      default: '',
    },
    /** Değerin önünde küçük görsel önizlemesi (URL) — görsel seçimi satırı; tek başına da değer sayılır. */
    valueImage: {
      type: String,
      default: '',
    },
    /** Değer boşken sağda soluk gösterilen metin (ör. "Masa seçin"); chevron korunur. */
    placeholder: {
      type: String,
      default: '',
    },
    /** Satır başı ikon karosu (`ui-icon-tile`) */
    icon: {
      type: String,
      default: '',
    },
    iconType: iconTypeProp,
    /** İkon karosu tonu (`ui-icon-tile` `color`) */
    iconColor: {
      type: String,
      default: '',
    },
    /** İkon karosu hex rengi (`ui-icon-tile` `hex`) — kategori / marka rengi */
    iconHex: {
      type: String,
      default: '',
    },
    /** `soft` | `solid` — hex verildiğinde varsayılan `solid` */
    iconVariant: {
      type: String,
      default: '',
    },
    /** `danger`: başlık tehlike tonunda (ör. hesabı sil) · `primary`: ekleme satırı (ör. "Tarih ekle") */
    color: {
      type: String,
      default: '',
      validator: (v) => !v || ITEM_COLORS.includes(v),
    },
    /** sm / md: 14px başlık · lg: 16px başlık */
    size: {
      type: String,
      default: 'md',
      validator: (v) => SIZES.includes(v),
    },
    /** `vue-router` hedefi — satır bağlantı olur */
    to: {
      type: [String, Object],
      default: undefined,
    },
    /** Satır düğme olur ve `click` yayar */
    interactive: {
      type: Boolean,
      default: false,
    },
    disabled: {
      type: Boolean,
      default: false,
    },
    /** Tıklanabilir satırda sağ gösterge: `chevron` | `external` | `copy` (değeri kopyalar) | `none` */
    trailingIcon: {
      type: String,
      default: 'chevron',
      validator: (v) => TRAILING_ICONS.includes(v),
    },
    /**
     * Değer varken satırın sağında temizle (×) düğmesi; `clear` yayar. Chevron yerine çizilir.
     * Seçim satırlarında (masa, kategori) seçimi kaldırmak için.
     */
    clearable: {
      type: Boolean,
      default: false,
    },
    clearLabel: {
      type: String,
      default: '',
    },
  },
  emits: ['click', 'clear'],
  computed: {
    resolvedValueIconType() {
      return resolveThemeIconType(this.uiDefaults, this.valueIconType)
    },
    resolvedPrefixIconType() {
      return resolveThemeIconType(this.uiDefaults, this.prefixIconType)
    },
    usesRowLayout() {
      return Boolean(this.title || this.description || this.value || this.icon || this.$slots.title)
    },
    actionable() {
      return this.interactive || this.to != null
    },
    actionBind() {
      if (!this.actionable) return {}
      return {
        type: 'button',
        variant: 'nav',
        color: this.color === 'danger' ? 'danger' : 'secondary',
        size: 'lg',
        block: true,
        textAlign: 'left',
        wrap: true,
        disabled: this.disabled,
        to: this.to,
      }
    },
    tileSize() {
      return TILE_SIZE_BY_ITEM[this.size] || 'sm'
    },
    resolvedIconVariant() {
      return this.iconVariant || (this.iconHex ? 'solid' : 'soft')
    },
    showClear() {
      return this.usesRowLayout && this.clearable && this.hasValue && !this.disabled
    },
    resolvedClearLabel() {
      return this.clearLabel || resolveUiText(this, 'ui.listItem.clear', 'Clear')
    },
    hasValue() {
      return Boolean(this.value || this.valueIcon || this.valueSwatch || this.valueImage)
    },
    resolvedTrailingIcon() {
      if (!this.actionable || this.$slots.trailing || this.showClear) return ''
      if (this.trailingIcon === 'external') return 'arrow-up-right-from-square'
      if (this.trailingIcon === 'copy') return 'copy'
      if (this.trailingIcon === 'chevron') return 'chevron-right'
      return ''
    },
    titleClass() {
      return cn('ui-list-item-title', this.color ? `ui-list-item-title--${this.color}` : '')
    },
    itemClass() {
      if (this.usesRowLayout) {
        return cn(
          'ui-list-item',
          'ui-list-item--row',
          `ui-list-item--${this.size}`,
          this.actionable ? 'ui-list-item--actionable' : '',
          this.disabled ? 'ui-list-item--disabled' : '',
          this.showClear ? 'ui-list-item--clearable' : '',
        )
      }
      return cn(
        'ui-list-item',
        this.align === 'center' ? 'ui-list-item--center' : '',
      )
    },
  },
  methods: {
    onClick(event) {
      if (!this.actionable || this.disabled) return
      this.$emit('click', event)
    },
    /** Serbest içerik düzeninde (geriye uyumlu) satır tıklaması `click` olarak iletilir. */
    onRootClick(event) {
      if (this.usesRowLayout) return
      this.$emit('click', event)
    },
  },
}
</script>
